import {CopilotIcon} from '@primer/octicons-react'
import {FormControl, TextInput, Spinner} from '@primer/react'
import {useState, useEffect, useRef} from 'react'
import {useSessionStorage, clearSessionStorage} from '@github-ui/use-safe-storage/session-storage'
import {useGeneratePullTitle} from './use-generate-pull-title'
import type {CopilotGeneratePullTitleAuthInfo, Commit} from './types'
import {useTrackPullTitleAcceptance} from './utilities/use-track-pull-title-acceptance'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {useQuickSubmitHandler} from './utilities/use-quick-submit-handler'
import {getPullTitleStorageKey} from './utilities/get-storage-key'

export interface CopilotGeneratePullTitleProps {
  defaultTitle: string
  emojiSuggestionsPath?: string
  authInfo: CopilotGeneratePullTitleAuthInfo
  commits: Commit[]
}

export function CopilotGeneratePullTitle({
  defaultTitle,
  emojiSuggestionsPath,
  authInfo,
  commits,
}: CopilotGeneratePullTitleProps) {
  const textExpanderRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const handleSubmitRef = useRef<() => void>(() => {})
  const onTextExpanderCommittedRef = useRef<() => void>(() => {})
  const storageKey = getPullTitleStorageKey()
  const [storedTitle, setStoredTitle] = useSessionStorage<string>(storageKey, defaultTitle)
  // Track a dissociated title value for when the form is submitting
  // This prevents the input from being cleared when session storage is cleared
  const [submittedTitle, setSubmittedTitle] = useState<string | null>(null)
  const title = submittedTitle ?? storedTitle
  const [regenerateCallCount, setRegenerateCallCount] = useState(0)
  const trackPullTitleAcceptance = useTrackPullTitleAcceptance()
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  // Track when component is shown if access is allowed
  useEffect(() => {
    if (authInfo.accessAllowed) {
      sendClickAnalyticsEvent({
        category: 'copilot_generate_pull_title',
        action: 'shown',
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []) // Only run once on mount
  const {generatedPullTitle, isFetching} = useGeneratePullTitle(defaultTitle, authInfo, commits, regenerateCallCount)

  // Store handleSubmit in a ref so it can access current state without re-creating
  // eslint-disable-next-line react-hooks/refs
  handleSubmitRef.current = () => {
    // Capture the current title value before clearing session storage
    // This prevents the controlled input from losing its value during form submission
    const currentTitle = inputRef.current?.value ?? title
    setSubmittedTitle(currentTitle)

    trackPullTitleAcceptance({
      title: currentTitle,
      defaultTitle,
      generatedTitle: generatedPullTitle?.title,
      regenerateCallCount,
    })
    // Clear session storage after capturing the value so the title doesn't persist
    clearSessionStorage([storageKey])
  }

  // Store onTextExpanderCommitted in a ref so it can access current state without re-creating
  // eslint-disable-next-line react-hooks/refs
  onTextExpanderCommittedRef.current = () => {
    setStoredTitle(inputRef.current?.value ?? title)
  }

  // Import text-expander only in browser environment
  useEffect(() => {
    if (typeof window !== 'undefined') {
      import('@github/text-expander-element')
    }
  }, [])

  useEffect(() => {
    const innerTextExpanderRef = textExpanderRef.current
    const onTextExpanderCommitted = () => {
      onTextExpanderCommittedRef.current()
    }

    innerTextExpanderRef?.addEventListener('text-expander-committed', onTextExpanderCommitted)

    return () => {
      innerTextExpanderRef?.removeEventListener('text-expander-committed', onTextExpanderCommitted)
    }
  }, [])

  // Update title when generation completes successfully
  useEffect(() => {
    if (generatedPullTitle?.title && !isFetching) {
      setStoredTitle(generatedPullTitle.title)
    }
  }, [generatedPullTitle, isFetching, setStoredTitle])

  function generatePullTitle() {
    setRegenerateCallCount(prev => prev + 1)
  }

  const handleKeyDown = useQuickSubmitHandler(inputRef)

  useEffect(() => {
    const parentForm = inputRef.current?.closest('form')
    const handleSubmit = () => {
      handleSubmitRef.current()
    }

    if (parentForm) {
      parentForm.addEventListener('submit', handleSubmit)
    }

    return () => {
      if (parentForm) {
        parentForm.removeEventListener('submit', handleSubmit)
      }
    }
  }, [])

  const isGenerating = isFetching

  return (
    <text-expander keys=":" data-emoji-url={emojiSuggestionsPath} class="position-relative" ref={textExpanderRef}>
      <FormControl required>
        <FormControl.Label className="f4">Add a title</FormControl.Label>
        <TextInput
          name="pull_request[title]"
          className="required title"
          placeholder="Title"
          onChange={event => setStoredTitle(event.target.value)}
          onKeyDown={handleKeyDown}
          value={title}
          aria-labelledby="pull_request_title_header"
          autoFocus
          autoComplete="off"
          block
          ref={inputRef}
          trailingAction={
            authInfo.accessAllowed ? (
              isGenerating ? (
                <TextInput.Action
                  icon={() => <Spinner size="small" />}
                  aria-label="Generating pull request title..."
                  disabled
                />
              ) : (
                <TextInput.Action
                  onClick={() => generatePullTitle()}
                  icon={CopilotIcon}
                  aria-label="Generate pull request title with Copilot"
                />
              )
            ) : undefined
          }
        />
      </FormControl>
    </text-expander>
  )
}
